preConditionHook:
// THE FIRST PULLBACK OF A STRONG BULL SPIKE -- the high 1. After spikeBars
// consecutive strong bull trend bars, the first bar whose low is below the
// prior bar's low is the signal bar, and the entry fires when a bar within maxWaitBars closes above
// that signal bar's high. Mirror: the low 1 after a bear spike.
//
// KEPT AS A COMPOSITE, deliberately, on both of the corpus's grounds: it is a
// named Brooks setup stated whole in all three sources, and its trigger is
// against a bar at a VARIABLE lag -- the pane cannot AND CloseAbovePriorHigh
// at a fixed lag with a spike filter and get this rule.
//
// IT IS NOT HighLowBarCount AT countTarget 1. That counter's cycle resets on a
// fresh N-bar high and it fires on the higher-high bar itself; this rule's
// reset is a completed spike and its trigger is a LATER bar closing over a
// retained level.
//
// SPIKE = StrongTrendBarRun's definition, the settled one: each bar closes
// above its own open with a body of at least bodyFraction of its own range.
// bodyFraction was implicit in the sources ('strong bull trend bars') and is
// promoted to an input at the corpus default 0.6. spikeBars 3 is the merged
// default (two sources say 3, one says 4).
//
// The scan runs oldest-last, so it ends on the OLDEST qualifying bar in the
// window -- the FIRST pullback bar after the spike, not the most recent one.
// The signal bar's high is retained in a local rather than read back through
// a variable offset. Both sides are computed unconditionally here: EL does
// not short-circuit, so a scan in a condition would run on every bar in EL
// and only on some bars in C++. Brooks's caveat 'but not after a buy climax'
// is a separate filter the pane ANDs, and is not carried here.
haveSigUp = false;
haveSigDn = false;
sigHighUp = 0.0;
sigLowDn = 0.0;
for (jj = 1; jj <= (int)maxWaitBars; ++jj) {
    spikeUpOk = true;
    spikeDnOk = true;
    for (ii = jj + 1; ii <= jj + (int)spikeBars; ++ii) {
        if (el_le(close[ii], open[ii])) spikeUpOk = false;
        if (el_lt(close[ii] - open[ii], bodyFraction * (high[ii] - low[ii]))) spikeUpOk = false;
        if (el_ge(close[ii], open[ii])) spikeDnOk = false;
        if (el_lt(open[ii] - close[ii], bodyFraction * (high[ii] - low[ii]))) spikeDnOk = false;
    }
    if (spikeUpOk && el_lt(low[jj], low[jj + 1])) {
        haveSigUp = true;
        sigHighUp = high[jj];
    }
    if (spikeDnOk && el_gt(high[jj], high[jj + 1])) {
        haveSigDn = true;
        sigLowDn = low[jj];
    }
}
